  const expectedDiscount = (5 * 8500) * 0.2 + 120000 * 0.05;
  const line1DiscountedAmount = (5 * 8500) - expectedDiscount;
  const line2DiscountedAmount = 120000 * 0.95;
  const expectedVat = Math.round((line1DiscountedAmount * 0.21) * 100) / 100 + Math.round((line2DiscountedAmount * 0.21) * 100) / 100;
