test('invoiceTotals with real invoices from createInvoice and discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  const expectedSubtotal = 5 * 8500 + 1 * 120000;
  const expectedDiscount = (5 * 8500) * 0.2 + 120000 * 0.05;
  const line1DiscountedAmount = (5 * 8500) - expectedDiscount;
  const line2DiscountedAmount = 120000 * 0.95;
  const expectedVat = Math.round((line1DiscountedAmount * 0.21) * 100) / 100 + Math.round((line2DiscountedAmount * 0.21) * 100) / 100;
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;
  assert.equal(r.value.subtotal, expectedSubtotal);
  assert.equal(r.value.discount, expectedDiscount);
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

